def div_even_odd(lst):
    first_odd = None
    first_even = None
    for num in lst:
        if num % 2 != 0:
            if first_odd is None:
                first_odd = num
        else:
            if first_even is None:
                first_even = num
        if first_odd is not None and first_even is not None:
            break
    return first_even // first_odd

